  public function executeUpdate()
  {
    if (!$this->getRequestParameter('clprestamo_id'))
    {
      $cl_prestamo = new ClPrestamo();
    }
    else
    {
      $cl_prestamo = ClPrestamoPeer::retrieveByPk($this->getRequestParameter('clprestamo_id'));
      $this->forward404Unless($cl_prestamo);
    }

    $cl_prestamo->setClprestamoId($this->getRequestParameter('clprestamo_id'));
    $cl_prestamo->setRegionalId($this->getRequestParameter('regional_id') ? $this->getRequestParameter('regional_id') : null);
    $cl_prestamo->setUsuarioId($this->getRequestParameter('usuario_id') ? $this->getRequestParameter('usuario_id') : null);
    $cl_prestamo->setClestadoprestamoId($this->getRequestParameter('clestadoprestamo_id') ? $this->getRequestParameter('clestadoprestamo_id') : null);
    $cl_prestamo->setPeriodoId($this->getRequestParameter('periodo_id') ? $this->getRequestParameter('periodo_id') : null);
    if ($this->getRequestParameter('fecha_prestamo'))
    {
      list($d, $m, $y) = sfI18N::getDateForCulture($this->getRequestParameter('fecha_prestamo'), $this->getUser()->getCulture());
      $cl_prestamo->setFechaPrestamo("$y-$m-$d");
    }
    if ($this->getRequestParameter('fecha_vencimiento'))
    {
      list($d, $m, $y) = sfI18N::getDateForCulture($this->getRequestParameter('fecha_vencimiento'), $this->getUser()->getCulture());
      $cl_prestamo->setFechaVencimiento("$y-$m-$d");
    }
    if ($this->getRequestParameter('fecha_devolucion'))
    {
      list($d, $m, $y) = sfI18N::getDateForCulture($this->getRequestParameter('fecha_devolucion'), $this->getUser()->getCulture());
      $cl_prestamo->setFechaDevolucion("$y-$m-$d");
    }
    $cl_prestamo->setObservaciones($this->getRequestParameter('observaciones'));
    $cl_prestamo->setConsecutivoRegional($this->getRequestParameter('consecutivo_regional'));
    $cl_prestamo->setNumeroRadicacion($this->getRequestParameter('numero_radicacion'));

    $cl_prestamo->save();

    return $this->redirect($this->getRequest()->getScriptName().'/prestamo_cliente/show?clprestamo_id='.$cl_prestamo->getClprestamoId());
  }
  
  public function executeUpdateDevolver()
  {   	 	
  	/************************Cambio Estado de la solicitud en la tabla ClDetallePrestamo***************************/
  	$c =  new Criteria();
  	$c->add(ClDetallePrestamoPeer::CLSOLICITUDPRESTAMO_ID,$this->getRequestParameter('clsolicitudprestamo_id'));
  	$resp  = ClDetallePrestamoPeer::doSelectOne($c);  	  	
	$resp->setClestadoprestamoId(2);
	$resp->save();
	/**************************************************************************************************************/			
	/***********************Verifica Estado de la solicitud Para asi Cambiar estado del Prestamo*******************/
	$a = new Criteria();
	$a->add(ClDetallePrestamoPeer::CLPRESTAMO_ID,$this->getRequestParameter('clprestamo_id'));
	$a->add(ClDetallePrestamoPeer::CLESTADOPRESTAMO_ID,1);
	$temp = ClDetallePrestamoPeer::doCount($a);
	if($temp == 0){		
		$prestamo = ClPrestamoPeer::retrieveByPK($this->getRequestParameter('clprestamo_id'));
		$prestamo->setClestadoprestamoId(2);
		$prestamo->setFechaDevolucion(date("Y-m-d"));
		$prestamo->save();
	}	
	/**************************************************************************************************************/
	$this->redirect('prestamo_cliente/show?clprestamo_id='.$this->getRequestParameter('clprestamo_id'));		
  }	
  
  public function executeMail()
  {
  	$c  = new Criteria();
  	$parametros = '';
  	/**************************************************************************************************************/
	if($this->getRequestParameter('vencidos')){
		$c->setDistinct();
		$c->addJoin(ClPrestamoPeer::CLPRESTAMO_ID,ClDetallePrestamoPeer::CLPRESTAMO_ID);						
		$c->add(ClPrestamoPeer::FECHA_VENCIMIENTO, $this->getRequestParameter('vencidos'),Criteria::LESS_THAN);
		//$c->add(PrestamoPeer::FECHA_DEVOLUCION,$this->getRequestParameter('vencidos') ,Criteria::LESS_THAN);
		$c->add(ClDetallePrestamoPeer::CLESTADOPRESTAMO_ID,1);
		$parametros .= "&vencidos=".$this->getRequestParameter('vencidos');								
	}
	/**************************************************************************************************************/
	$c->addAscendingOrderByColumn(ClPrestamoPeer::CLPRESTAMO_ID);
	$resp          = ClPrestamoPeer::doSelect($c);
	$parametro     = ParametroPeer::retrieveByPK(35);
	$cuerpo        = $parametro->getValortexto();
	$datos  = array();
	$cuenta = array();
	$texto ='';
	$e_mail='';
	foreach($resp as $resul){
		$a = new Criteria();
		$a->add(ClDetallePrestamoPeer::CLPRESTAMO_ID,$resul->getClprestamoId());
		$a->add(ClDetallePrestamoPeer::CLESTADOPRESTAMO_ID,1);
		$obj = ClDetallePrestamoPeer::doSelect($a);
		$texto ='';
		$e_mail='';
		foreach($obj as $detalle){
		  $texto .= $detalle->getClSolicitudPrestamo()->getClienteId().'-'.$detalle->getClSolicitudPrestamo()->getCliente()->getNombreCliente().', ';
		  $e_mail = $detalle->getClSolicitudPrestamo()->getUsuario()->getEmail(); 	
		}
		$datos[]  = $cuerpo.$texto;
		$cuenta[] = $e_mail;
		//*********************************************************************************************************************
		$baseMail = new BaseMailSimad();
		$baseMail->SetSubject('CAD : Prestamo de documentos');
		$baseMail->SetMsgHTML($cuerpo.$texto);
		$baseMail->SetAddAddress($e_mail, $e_mail);    
		if($baseMail->InitSend() === true)
		{
		   $baseMail->writetolog("Alerta enviada: " . $e_mail . " Enviado a: " . $e_mail);
		}else{
		   $baseMail->writetolog("Error al enviar alerta: " . $e_mail . " Cuenta correo: " . $e_mail);
		}
		//***********************************************************************************************************************
	}	
	$this->datos = $datos;
	$this->cuenta = $cuenta;										
	/**************************************************************************************************************/
  }
  
  public function executeDevolverTodos()
  {
  	/*******************************Cambiar Estado Del Prestamo****************************************************/
  	$prestamo = ClPrestamoPeer::retrieveByPK($this->getRequestParameter('clprestamo_id'));
  	$prestamo->setClestadoprestamoId(2);
  	$prestamo->setFechaDevolucion(date("Y-m-d"));
  	$prestamo->save();
	/**************************************************************************************************************/  	
  	
  	/***********************Cambiar Estado De Los Detalles del Prestamo********************************************/
  	$c = new Criteria();
  	$c->add(ClDetallePrestamoPeer::CLPRESTAMO_ID,$this->getRequestParameter('clprestamo_id'));
  	$c->add(ClDetallePrestamoPeer::CLESTADOPRESTAMO_ID,1);
  	$prestados =  ClDetallePrestamoPeer::doSelect($c);
	foreach($prestados as $result){
		$result->setClestadoprestamoId(2);		
		$result->save();
	}    
	/**************************************************************************************************************/
	//$this->redirect('prestamo/show?prestamo_id='.$prestamo->getPrestamoId());
	$this->redirect('prestamo_cliente/show?clprestamo_id='.$this->getRequestParameter('clprestamo_id'));	
  }
  
