	/**************************************************************************************************************/
	if($this->getRequestParameter('cl_estado_prestamo_id')){
		$c->add(ClPrestamoPeer::CLESTADOPRESTAMO_ID, $this->getRequestParameter('cl_estado_prestamo_id'));
		$parametros .= "&cl_estado_prestamo_id=".$this->getRequestParameter('cl_estado_prestamo_id');		
	}
	/**************************************************************************************************************/
	if ($this->getRequestParameter('fechaInicial')) {
			if ($this->getRequestParameter('fechaFinal')) {
	            $c->add(ClPrestamoPeer::FECHA_PRESTAMO,$this->getRequestParameter('fechaInicial'),Criteria::GREATER_THAN);
	            $c->addAnd(ClPrestamoPeer::FECHA_PRESTAMO,$this->getRequestParameter('fechaFinal'),Criteria::LESS_THAN);
	            $this->parametros .= "&fechaInicial=" . $this->getRequestParameter('fechaInicial');
	        }else{
			    $c->add(ClPrestamoPeer::FECHA_PRESTAMO,$this->getRequestParameter('fechaInicial'),Criteria::GREATER_THAN);
			    $this->parametros .= "&fechaInicial=" . $this->getRequestParameter('fechaInicial');
		    }
	    }	    	    
	/**************************************************************************************************************/
	if($this->getRequestParameter('subserie_id')){			
		$c->addJoin(ClPrestamoPeer::CLPRESTAMO_ID, ClDetallePrestamoPeer::CLPRESTAMO_ID);
	    $c->addJoin(ClDetallePrestamoPeer::CLSOLICITUDPRESTAMO_ID, SolicitudPrestamoPeer::CLSOLICITUDPRESTAMO_ID);
	    $c->addJoin(ClSolicitudPrestamoPeer::CLIENTE_ID, ClientePeer::CLIENTE_ID);
		$c->addJoin(ClientePeer::SUBSERIE_ID, SubseriePeer::SUBSERIE_ID);	    
	    $c->add(SubseriePeer::SUBSERIE_ID,$this->getRequestParameter('subserie_id'));
		$parametros .= "&subserie_id=".$this->getRequestParameter('subserie_id');			
	}
	/**************************************************************************************************************/
	if($this->getRequestParameter('responsable')){			
		$c->addJoin(ClPrestamoPeer::CLPRESTAMO_ID, ClDetallePrestamoPeer::CLPRESTAMO_ID);
	    $c->addJoin(ClDetallePrestamoPeer::CLSOLICITUDPRESTAMO_ID, ClSolicitudPrestamoPeer::CLSOLICITUDPRESTAMO_ID);
	    $c->addJoin(ClSolicitudPrestamoPeer::CLIENTE_ID, ClientePeer::CLIENTE_ID);
		$c->addJoin(ClientePeer::CLIENTE_ID, ClUsuarioPeer::CLIENTE_ID);	    
	    $c->add(ClUsuarioPeer::USUARIO_ID,$this->getRequestParameter('responsable'));
	    $c->add(ClUsuarioPeer::ROL_CLUSUARIO_ID,1);
		$parametros .= "&responsable=".$this->getRequestParameter('responsable');			
	}
	/**************************************************************************************************************/
	if($this->getRequestParameter('prestadoPor')){
		$c->add(ClPrestamoPeer::USUARIO_ID, $this->getRequestParameter('prestadoPor'));
		$parametros .= "&prestadoPor=".$this->getRequestParameter('prestadoPor');		
	}
	/**************************************************************************************************************/
	if($this->getRequestParameter('vencidos')?true:false){
		$c->addJoin(ClPrestamoPeer::CLPRESTAMO_ID,ClDetallePrestamoPeer::CLPRESTAMO_ID);						
		$c->add(ClPrestamoPeer::FECHA_VENCIMIENTO, $this->getRequestParameter('vencidos'),Criteria::LESS_THAN);
		$c->add(ClPrestamoPeer::FECHA_DEVOLUCION,$this->getRequestParameter('vencidos') ,Criteria::LESS_THAN);
		$c->add(ClDetallePrestamoPeer::CLESTADOPRESTAMO_ID,1);
		$parametros .= "&vencidos=".$this->getRequestParameter('vencidos');								
	}
    /**************************************************************************************************************/	$c->addDescendingOrderByColumn(ClDetallePrestamoPeer::CLPRESTAMO_ID);
    $pager = new sfPropelPager('ClDetallePrestamo', 10);
    $pager->setCriteria($c);        
    $pager->setPage($this->getRequestParameter('page', 1));
    $pager->init();
    $this->pager = $pager;
    $this->parametros = $parametros;    
	/*************************************************************************************************************/
  }	
  
  public function executeDelete()
  {
    $cl_prestamo = ClPrestamoPeer::retrieveByPk($this->getRequestParameter('clprestamo_id'));

    $this->forward404Unless($cl_prestamo);

    $cl_prestamo->delete();

    return $this->redirect($this->getRequest()->getScriptName().'/prestamo_cliente/list');
  }
}
